namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public string ImageUrl { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough, San Marzano tomatoes, Fresh mozzarella, Fresh basil, Olive oil, Salt",
            Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute.\n5. Bake 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil.",
            ImageUrl = "🍕", AverageRating = 4.5, RatingCount = 12
        },
        new Recipe
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti, Guanciale, Egg yolks, Pecorino Romano, Black pepper",
            Steps = "1. Cook spaghetti in salted water.\n2. Crisp guanciale in a pan.\n3. Whisk egg yolks with grated pecorino.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, stir in egg mixture.\n6. Season with black pepper and serve.",
            ImageUrl = "🍝", AverageRating = 4.8, RatingCount = 20
        },
        new Recipe
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Onion, Garlic, Ginger",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and garam masala.\n5. Simmer, add cream and chicken pieces.\n6. Cook 10 minutes and serve with rice.",
            ImageUrl = "🍛", AverageRating = 4.7, RatingCount = 15
        },
        new Recipe
        {
            Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
            Ingredients = "Rice noodles, Tofu, Bean sprouts, Peanuts, Lime, Tamarind paste, Fish sauce, Sugar",
            Steps = "1. Soak rice noodles in warm water.\n2. Press and cube tofu, pan-fry until golden.\n3. Mix tamarind paste, fish sauce, and sugar for sauce.\n4. Stir-fry noodles with sauce.\n5. Add tofu and bean sprouts.\n6. Garnish with peanuts and lime wedges.",
            ImageUrl = "🍜", AverageRating = 4.3, RatingCount = 8
        },
        new Recipe
        {
            Id = 5, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheddar cheese, Sour cream, Cumin, Chili powder",
            Steps = "1. Brown ground beef with cumin and chili powder.\n2. Warm taco shells in oven.\n3. Dice lettuce and tomatoes.\n4. Shred cheddar cheese.\n5. Assemble tacos with beef and toppings.\n6. Serve with sour cream and salsa.",
            ImageUrl = "🌮", AverageRating = 4.2, RatingCount = 10
        },
        new Recipe
        {
            Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
            Ingredients = "Dark chocolate, Butter, Eggs, Sugar, Flour, Vanilla extract",
            Steps = "1. Preheat oven to 425°F.\n2. Melt chocolate and butter together.\n3. Whisk eggs with sugar and vanilla.\n4. Fold chocolate mixture into eggs.\n5. Add flour gently.\n6. Bake in greased ramekins 12-14 minutes.\n7. Invert onto plate and serve immediately.",
            ImageUrl = "🍫", AverageRating = 4.9, RatingCount = 25
        },
        new Recipe
        {
            Id = 7, Title = "Caesar Salad", Category = "Salads",
            Ingredients = "Romaine lettuce, Parmesan, Croutons, Anchovy paste, Garlic, Lemon juice, Olive oil, Egg yolk",
            Steps = "1. Whisk anchovy paste, garlic, lemon juice, and egg yolk.\n2. Slowly drizzle in olive oil to emulsify.\n3. Tear romaine into bite-sized pieces.\n4. Toss lettuce with dressing.\n5. Top with shaved parmesan and croutons.\n6. Serve immediately.",
            ImageUrl = "🥗", AverageRating = 4.0, RatingCount = 6
        },
        new Recipe
        {
            Id = 8, Title = "Miso Ramen", Category = "Asian",
            Ingredients = "Ramen noodles, Miso paste, Pork belly, Soft-boiled egg, Green onions, Nori, Chicken broth",
            Steps = "1. Simmer chicken broth and whisk in miso paste.\n2. Slice and sear pork belly until caramelized.\n3. Cook ramen noodles according to package.\n4. Prepare soft-boiled eggs (6 minutes).\n5. Assemble bowls with noodles and broth.\n6. Top with pork, egg, nori, and green onions.",
            ImageUrl = "🍜", AverageRating = 4.6, RatingCount = 14
        }
    };

    private readonly Dictionary<int, List<int>> _ratings = new();

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        var recipe = GetRecipeById(recipeId);
        if (recipe == null) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);
        recipe.RatingCount = _ratings[recipeId].Count;
        recipe.AverageRating = _ratings[recipeId].Average();
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }
}

