@page "/"
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>RecipeHub — Home</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">🍳 Welcome to RecipeHub</h1>
    <p class="lead text-muted">Discover and share delicious recipes from around the world</p>
</div>

<h2 class="mb-4">Browse by Category</h2>

<div class="row g-4">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-4 col-sm-6">
            <a href="/category/@category" class="text-decoration-none">
                <div class="card h-100 shadow-sm border-0">
                    <div class="card-body text-center p-4">
                        <span class="display-5">@GetCategoryEmoji(category)</span>
                        <h3 class="card-title mt-3">@category</h3>
                        <p class="text-muted">@RecipeService.GetRecipesByCategory(category).Count recipes</p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

