@rendermode InteractiveServer
@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="my-3">
    <div class="d-flex justify-content-center gap-1 fs-3" role="group" aria-label="Star rating">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-link p-0 text-decoration-none"
                    @onclick="() => Rate(star)"
                    @onmouseover="() => HoverStar = star"
                    @onmouseout="() => HoverStar = 0"
                    aria-label="Rate @star stars">
                <span style="cursor:pointer;">@(star <= DisplayStars ? "★" : "☆")</span>
            </button>
        }
    </div>
    <p class="text-muted text-center mt-2 mb-0">
        @if (UserRating > 0)
        {
            <span class="text-success">You rated this @UserRating star@(UserRating > 1 ? "s" : "")!</span>
        }
        else
        {
            <span>⭐ @CurrentRating.ToString("F1") (@RatingCount ratings)</span>
        }
    </p>
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int HoverStar { get; set; }
    private int UserRating { get; set; }

    private int DisplayStars => HoverStar > 0 ? HoverStar : (UserRating > 0 ? UserRating : (int)Math.Round(CurrentRating));

    private void Rate(int stars)
    {
        UserRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe != null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
    }
}

