toolArgs.file_text:
@page "/submit"
@rendermode InteractiveServer
@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService

<PageTitle>Submit a Recipe — RecipeHub</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your culinary creations with the community!</p>

@if (Submitted)
{
    <div class="alert alert-success">
        <h4>🎉 Recipe submitted!</h4>
        <p>Your recipe "<strong>@NewRecipe.Title</strong>" has been added to the @NewRecipe.Category category.</p>
        <a href="/category/@NewRecipe.Category" class="btn btn-outline-success">View Category</a>
        <button class="btn btn-outline-primary ms-2" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <EditForm Model="NewRecipe" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
                <DataAnnotationsValidator />
                <ValidationSummary class="text-danger" />

                <div class="mb-3">
                    <label for="title" class="form-label fw-bold">Recipe Title</label>
                    <InputText id="title" @bind-Value="NewRecipe.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
                </div>

                <div class="mb-3">
                    <label for="category" class="form-label fw-bold">Category</label>
                    <InputSelect id="category" @bind-Value="NewRecipe.Category" class="form-select">
                        <option value="">— Select a category —</option>
                        @foreach (var cat in Categories)
                        {
                            <option value="@cat">@cat</option>
                        }
                        <option value="Other">Other</option>
                    </InputSelect>
                </div>

                <div class="mb-3">
                    <label for="ingredients" class="form-label fw-bold">Ingredients</label>
                    <InputTextArea id="ingredients" @bind-Value="NewRecipe.Ingredients" class="form-control" rows="4"
                                   placeholder="Comma-separated list: flour, sugar, butter, apples..." />
                    <div class="form-text">Separate ingredients with commas.</div>
                </div>

                <div class="mb-3">
                    <label for="steps" class="form-label fw-bold">Steps</label>
                    <InputTextArea id="steps" @bind-Value="NewRecipe.Steps" class="form-control" rows="6"
                                   placeholder="1. Preheat oven to 350°F.&#10;2. Mix dry ingredients.&#10;3. ..." />
                    <div class="form-text">Write each step on a new line.</div>
                </div>

                <button type="submit" class="btn btn-primary btn-lg" disabled="@(!IsValid)">
                    🍳 Submit Recipe
                </button>
            </EditForm>
        </div>
    </div>
}

@code {
    private Recipe NewRecipe { get; set; } = new();
    private bool Submitted { get; set; }
    private List<string> Categories { get; set; } = new();

    private bool IsValid => !string.IsNullOrWhiteSpace(NewRecipe.Title)
                         && !string.IsNullOrWhiteSpace(NewRecipe.Category)
                         && !string.IsNullOrWhiteSpace(NewRecipe.Ingredients)
                         && !string.IsNullOrWhiteSpace(NewRecipe.Steps);

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        if (!IsValid) return;
        NewRecipe.ImageUrl = "🍽️";
        RecipeService.AddRecipe(NewRecipe);
        Submitted = true;
    }

    private void Reset()
    {
        NewRecipe = new Recipe();
        Submitted = false;
    }
}

